import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    res = []
    for num in a:
        if num == 0:
            res.append(0)
            continue
        steps = 0
        while num != 0:
            if num % 2 == 1:
                steps += 1
                num = (num + 1) % 32768
            else:
                num = (num // 2) % 32768
                steps += 1
        res.append(steps)
    print(' '.join(map(str, res)))

solve()
